const NO_START = /^[、。，．・：；？！ー〜）」』】〕〉》］｝ぁぃぅぇぉっゃゅょゎァィゥェォッャュョヮヵヶ々ゝゞ]+/;
const NO_END = /[（「『【〔〈《［｛]+$/;
/* a question sentence as the paper draws it: 【…】 underlined, （　　） a blank, and the four blanks of a
   sentence-order question (＿ and ★ for the starred one) kept together on one line */
const paperSegs = (text) => {
const out = [];
noRuby(text).split(/(【[^】]*】|（　　）|[＿★]+)/).filter((t) => t).forEach((t) => {
if (t === '（　　）') out.push({ blank: true });
else if (/^[＿★]+$/.test(t)) {
const prev = out[out.length - 1];
const lead = prev && prev.text && prev.line === 'none' ? (prev.t.match(NO_END) || [''])[0] : '';
if (lead) prev.t = prev.t.slice(0, -lead.length);
out.push({ slots: [...t].map((c) => ({ star: c === '★' })), lead, tail: '' });
} else if (t[0] === '【') out.push({ text: true, t: t.slice(1, -1), line: '2px solid #1B2440', ws: 'nowrap' });
else {
const prev = out[out.length - 1];
const tail = prev && prev.slots ? (t.match(NO_START) || [''])[0] : '';
if (tail) prev.tail = tail;
if (t.length > tail.length) out.push({ text: true, t: t.slice(tail.length), line: 'none', ws: 'normal' });
}
});
return out.filter((g) => !g.text || g.t);
};
/* a passage paragraph or a text of a pair: 【…】 underlined */
const lineSegs = (text) => noRuby(text).split(/(【[^】]*】)/).filter((t) => t).map((t) => (t[0] === '【' ? { t: t.slice(1, -1), line: '2px solid #1B2440' } : { t, line: 'none' }));
