const n = items.length + 1;
const it = { ...x, n, no: j + 1, options: (x.options || []).map((o) => N.plain(o)) };
if (x.kind === 'sentence') it.segs = paperSegs(x.ja);
if (x.passage) it.passage = x.passage.map((p) => ({ segs: lineSegs(p) }));
if (x.texts) it.texts = x.texts.map((t, i) => ({ tag: 'ABCD'[i], segs: lineSegs(t) }));
